// main.zig — swscale candidate: FFmpeg-compatible scaling / pixel-format conversion.
//
// The generic path mirrors libswscale's pipeline (input conversion -> horizontal
// filter to 15-bit -> vertical filter -> output writer) with filters built by the
// same integer arithmetic as initFilter, so results track the reference bit-for-bit.
// Same-size conversions FFmpeg handles with dedicated converters get equivalent
// dedicated (SIMD) kernels here.

const std = @import("std");
const k = @import("kernels.zig");

const alloc = std.heap.c_allocator;

pub const YUV420P = 0;
pub const YUV422P = 1;
pub const YUV444P = 2;
pub const NV12 = 3;
pub const NV21 = 4;
pub const RGB24 = 5;
pub const BGR24 = 6;
pub const RGBA = 7;
pub const BGRA = 8;
pub const GRAY8 = 9;

const NEAREST = 0;
const BILINEAR = 1;
const BICUBIC = 2;

fn isRGB(f: i32) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isPlanarYUV(f: i32) bool {
    return f <= NV21;
}
fn isSemi(f: i32) bool {
    return f == NV12 or f == NV21;
}
fn hasAlphaFmt(f: i32) bool {
    return f == RGBA or f == BGRA;
}
fn hSub(f: i32) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn vSub(f: i32) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn ceilShr(v: i32, s: u5) i32 {
    return -((-v) >> s);
}

// Byte offsets of R, G, B (and A) inside a packed pixel.
pub const RgbLayout = struct { r: usize, g: usize, b: usize, a: usize, bpp: usize };
pub fn layout(f: i32) RgbLayout {
    return switch (f) {
        RGB24 => .{ .r = 0, .g = 1, .b = 2, .a = 0, .bpp = 3 },
        BGR24 => .{ .r = 2, .g = 1, .b = 0, .a = 0, .bpp = 3 },
        RGBA => .{ .r = 0, .g = 1, .b = 2, .a = 3, .bpp = 4 },
        else => .{ .r = 2, .g = 1, .b = 0, .a = 3, .bpp = 4 },
    };
}

// ── filter construction (port of initFilter's integer arithmetic) ───────────

pub const Filter = struct {
    pos: []i32,
    coef: []i16,
    size: usize,
    n: usize,
};

fn avLog2(v: i64) i64 {
    if (v <= 0) return 0;
    return 63 - @as(i64, @clz(@as(u64, @intCast(v))));
}

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

fn initFilter(xInc: i64, srcW: i64, dstW: i64, one: i64, algo: i32, srcPos: i64, dstPos: i64) !Filter {
    const nd: usize = @intCast(dstW);
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(avLog2(@divTrunc(srcW, dstW)), 8));
    var filterSize: i64 = 0;
    var filter: []i64 = undefined;
    const pos = try alloc.alloc(i32, nd + 3);

    if (@abs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, nd);
        for (0..nd) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == NEAREST) {
        filterSize = 1;
        filter = try alloc.alloc(i64, nd);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..nd) |i| {
            const xx = (xDstInSrc - ((filterSize - 1) << 15) + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i64 = if (algo == BICUBIC) 4 else 2;
        if (xInc <= 1 << 16) {
            filterSize = 1 + sizeFactor;
        } else {
            filterSize = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        filterSize = @min(filterSize, srcW - 2);
        filterSize = @max(filterSize, 1);
        const fs: usize = @intCast(filterSize);
        filter = try alloc.alloc(i64, nd * fs);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        for (0..nd) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (filterSize - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..fs) |j| {
                var d: i64 = @as(i64, @intCast(@abs(xx * (1 << 17) - xDstInSrc))) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (algo == BICUBIC) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(0.6 * @as(f64, 1 << 24));
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * fs + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }

    // reduce filter size (step 1)
    const f2s: usize = @intCast(filterSize);
    var minFilterSize: usize = 0;
    var ii: isize = @as(isize, @intCast(nd)) - 1;
    const cutLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: usize = f2s;
        var cutOff: i64 = 0;
        for (0..f2s) |_| {
            cutOff += @intCast(@abs(filter[i * f2s]));
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            if (i < nd - 1 and pos[i] >= pos[i + 1]) break;
            var kk: usize = 1;
            while (kk < f2s) : (kk += 1) filter[i * f2s + kk - 1] = filter[i * f2s + kk];
            filter[i * f2s + kk - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var j: usize = f2s - 1;
        while (j > 0) : (j -= 1) {
            cutOff += @intCast(@abs(filter[i * f2s + j]));
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    const fsz = minFilterSize;
    const f3 = try alloc.alloc(i64, nd * fsz);
    defer alloc.free(f3);
    for (0..nd) |i| {
        for (0..fsz) |j| {
            f3[i * fsz + j] = if (j >= f2s) 0 else filter[i * f2s + j];
        }
    }
    alloc.free(filter);
    const sw: i32 = @intCast(srcW);
    const fszi: i32 = @intCast(fsz);
    // fix borders
    for (0..nd) |i| {
        const row = f3[i * fsz .. (i + 1) * fsz];
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < fsz) : (j += 1) {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                row[left] += row[j];
                row[j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + fszi > sw) {
            const shift: i32 = pos[i] + @min(fszi - sw, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (pos[i] + @as(i32, @intCast(j)) >= sw) {
                    acc += row[ju];
                    row[ju] = 0;
                }
            }
            j = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    row[ju] = 0;
                } else {
                    row[ju] = row[@intCast(j - shift)];
                }
            }
            pos[i] -= shift;
            row[@intCast(sw - 1 - pos[i])] += acc;
        }
    }
    // normalize
    const coef = try alloc.alloc(i16, fsz * (nd + 3));
    @memset(coef, 0);
    for (0..nd) |i| {
        var sum: i64 = 0;
        for (0..fsz) |j| sum += f3[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        var err: i64 = 0;
        for (0..fsz) |j| {
            const v = f3[i * fsz + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * fsz + j] = @intCast(intV);
            err = v - intV * sum;
        }
    }
    pos[nd] = pos[nd - 1];
    pos[nd + 1] = pos[nd - 1];
    pos[nd + 2] = pos[nd - 1];
    return .{ .pos = pos, .coef = coef, .size = fsz, .n = nd };
}

fn freeFilter(f: *Filter) void {
    alloc.free(f.pos);
    alloc.free(f.coef);
}

fn localPos(sub: u5) i64 {
    var p: i64 = (@as(i64, 128) << sub) - 128;
    p += 128;
    return p >> sub;
}

// ── colour tables ────────────────────────────────────────────────────────────

pub const YuvTables = struct {
    ytab: [2048]u8,
    // ytab index = base + off[U/V] + Y
    rOff: [256]i32,
    gUOff: [256]i32,
    gVOff: [256]i32,
    bOff: [256]i32,
    // full-chroma coefficients
    y_off: i32,
    y_coeff: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,
};

fn roundToInt16(f: i64) i32 {
    const r: i64 = (f + (1 << 15)) >> 16;
    if (r < -0x7FFF) return -0x8000;
    if (r > 0x7FFF) return 0x7FFF;
    return @intCast(r);
}

fn initYuvTables(t: *YuvTables) void {
    var crv: i64 = 104597;
    var cbu: i64 = 132201;
    var cgu: i64 = -25675;
    var cgv: i64 = -53279;
    var cy: i64 = 1 << 16;
    var oy: i64 = 0;
    cy = @divTrunc(cy * 255, 219);
    oy = 16 << 16;
    cy = (cy * 65536) >> 16;
    crv = (crv * 65536 * 65536) >> 32;
    cbu = (cbu * 65536 * 65536) >> 32;
    cgu = (cgu * 65536 * 65536) >> 32;
    cgv = (cgv * 65536 * 65536) >> 32;
    t.y_coeff = @as(i16, @truncate(roundToInt16(cy * (1 << 13))));
    t.y_off = @as(i16, @truncate(roundToInt16(oy * (1 << 9))));
    t.v2r = @as(i16, @truncate(roundToInt16(crv * (1 << 13))));
    t.v2g = @as(i16, @truncate(roundToInt16(cgv * (1 << 13))));
    t.u2g = @as(i16, @truncate(roundToInt16(cgu * (1 << 13))));
    t.u2b = @as(i16, @truncate(roundToInt16(cbu * (1 << 13))));
    crv = @divTrunc(crv * (1 << 16) + 0x8000, @max(cy, 1));
    cbu = @divTrunc(cbu * (1 << 16) + 0x8000, @max(cy, 1));
    cgu = @divTrunc(cgu * (1 << 16) + 0x8000, @max(cy, 1));
    cgv = @divTrunc(cgv * (1 << 16) + 0x8000, @max(cy, 1));
    var yb: i64 = -(384 << 16) - 512 * cy - oy;
    for (0..2048) |i| {
        const v = (yb + 0x8000) >> 16;
        t.ytab[i] = @intCast(std.math.clamp(v, 0, 255));
        yb += cy;
    }
    const yoffs: i32 = 326 + 512;
    for (0..256) |i| {
        const ii: i64 = @intCast(i);
        t.rOff[i] = yoffs - @as(i32, @intCast(crv >> 9)) + @as(i32, @intCast((ii * crv) >> 16));
        t.bOff[i] = yoffs - @as(i32, @intCast(cbu >> 9)) + @as(i32, @intCast((ii * cbu) >> 16));
        t.gUOff[i] = yoffs - @as(i32, @intCast(cgu >> 9)) + @as(i32, @intCast((ii * cgu) >> 16));
        t.gVOff[i] = -@as(i32, @intCast(cgv >> 9)) + @as(i32, @intCast((ii * cgv) >> 16));
    }
}

pub const Rgb2Yuv = struct { ry: i32, gy: i32, by: i32, ru: i32, gu: i32, bu: i32, rv: i32, gv: i32, bv: i32 };

fn cf(a: f64, m: f64) i32 {
    return @intFromFloat(a * m / 255.0 * 32768.0 + 0.5);
}

fn initRgb2Yuv() Rgb2Yuv {
    return .{
        .by = cf(0.114, 219),
        .bv = -cf(0.081, 224),
        .bu = cf(0.500, 224),
        .gy = cf(0.587, 219),
        .gv = -cf(0.419, 224),
        .gu = -cf(0.331, 224),
        .ry = cf(0.299, 219),
        .rv = cf(0.500, 224),
        .ru = -cf(0.169, 224),
    };
}

// ── context ──────────────────────────────────────────────────────────────────

const Mode = enum { generic, copy_same, planar_copy, yuv2rgb, nv12_to_planar, planar_to_nv12, bgr24_to_yv12, rgb_to_rgb };

pub const Ctx = struct {
    srcW: i32,
    srcH: i32,
    dstW: i32,
    dstH: i32,
    srcFmt: i32,
    dstFmt: i32,
    algo: i32,
    mode: Mode,

    tabs: YuvTables,
    c2y: Rgb2Yuv,

    // generic pipeline
    chrSrcHSub: u5 = 0,
    chrSrcVSub: u5 = 0,
    chrDstHSub: u5 = 0,
    chrDstVSub: u5 = 0,
    chrSrcW: i32 = 0,
    chrSrcH: i32 = 0,
    chrDstW: i32 = 0,
    chrDstH: i32 = 0,
    fullChr: bool = false,
    needAlpha: bool = false,
    hLum: Filter = undefined,
    hChr: Filter = undefined,
    vLum: Filter = undefined,
    vChr: Filter = undefined,
    lumBuf: []i16 = &.{},
    chrUBuf: []i16 = &.{},
    chrVBuf: []i16 = &.{},
    alpBuf: []i16 = &.{},
    lumDone: []u8 = &.{},
    chrDone: []u8 = &.{},
    lumStride: usize = 0,
    chrStride: usize = 0,
    tmpA: []i16 = &.{},
    tmpB: []i16 = &.{},
    tmpC: []i16 = &.{},
    tmp8a: []u8 = &.{},
    tmp8b: []u8 = &.{},
    hasFilters: bool = false,
};

fn setupGeneric(c: *Ctx) !void {
    const sf = c.srcFmt;
    const df = c.dstFmt;
    c.chrSrcHSub = hSub(sf);
    c.chrSrcVSub = vSub(sf);
    c.chrDstHSub = hSub(df);
    c.chrDstVSub = vSub(df);
    var full = false;
    if (isRGB(df)) {
        if (c.dstW & 1 != 0) full = true;
        if (c.chrSrcHSub == 0 and c.chrSrcVSub == 0) full = true;
        if (!full) c.chrDstHSub = 1;
    }
    c.fullChr = full;
    if (isRGB(sf) and ((c.dstW >> c.chrDstHSub) <= (c.srcW >> 1))) c.chrSrcHSub = 1;
    c.chrSrcW = ceilShr(c.srcW, c.chrSrcHSub);
    c.chrSrcH = ceilShr(c.srcH, c.chrSrcVSub);
    c.chrDstW = ceilShr(c.dstW, c.chrDstHSub);
    c.chrDstH = ceilShr(c.dstH, c.chrDstVSub);
    c.needAlpha = hasAlphaFmt(sf) and hasAlphaFmt(df);

    const sW: i64 = c.srcW;
    const sH: i64 = c.srcH;
    const dW: i64 = c.dstW;
    const dH: i64 = c.dstH;
    const lumXInc = @divTrunc((sW << 16) + (dW >> 1), dW);
    const lumYInc = @divTrunc((sH << 16) + (dH >> 1), dH);
    const cSW: i64 = c.chrSrcW;
    const cSH: i64 = c.chrSrcH;
    const cDW: i64 = c.chrDstW;
    const cDH: i64 = c.chrDstH;
    const chrXInc = @divTrunc((cSW << 16) + (cDW >> 1), cDW);
    const chrYInc = @divTrunc((cSH << 16) + (cDH >> 1), cDH);

    c.hLum = try initFilter(lumXInc, sW, dW, 1 << 14, c.algo, localPos(0), localPos(0));
    c.hChr = try initFilter(chrXInc, cSW, cDW, 1 << 14, c.algo, localPos(c.chrSrcHSub), localPos(c.chrDstHSub));
    c.vLum = try initFilter(lumYInc, sH, dH, 1 << 12, c.algo, localPos(0), localPos(0));
    c.vChr = try initFilter(chrYInc, cSH, cDH, 1 << 12, c.algo, localPos(c.chrSrcVSub), localPos(c.chrDstVSub));
    c.hasFilters = true;
    k.prepareHFilter(&c.hLum);
    k.prepareHFilter(&c.hChr);

    c.lumStride = (@as(usize, @intCast(c.dstW)) + 31) & ~@as(usize, 15);
    c.chrStride = (@as(usize, @intCast(c.chrDstW)) + 31) & ~@as(usize, 15);
    const sh: usize = @intCast(c.srcH);
    const csh: usize = @intCast(c.chrSrcH);
    c.lumBuf = try alloc.alloc(i16, c.lumStride * sh);
    c.chrUBuf = try alloc.alloc(i16, c.chrStride * csh);
    c.chrVBuf = try alloc.alloc(i16, c.chrStride * csh);
    if (c.needAlpha) c.alpBuf = try alloc.alloc(i16, c.lumStride * sh);
    c.lumDone = try alloc.alloc(u8, sh);
    c.chrDone = try alloc.alloc(u8, csh);
    const sw: usize = @intCast(c.srcW);
    c.tmpA = try alloc.alloc(i16, sw + 64);
    c.tmpB = try alloc.alloc(i16, sw + 64);
    c.tmpC = try alloc.alloc(i16, sw + 64);
    c.tmp8a = try alloc.alloc(u8, sw + 64);
    c.tmp8b = try alloc.alloc(u8, sw + 64);
    if (sf == GRAY8) {
        // no chroma in the source: FFmpeg feeds mid-grey (1 << 14)
        @memset(c.chrUBuf, 1 << 14);
        @memset(c.chrVBuf, 1 << 14);
    }
}

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    if (src_w <= 0 or src_h <= 0 or dst_w <= 0 or dst_h <= 0) return null;
    if (src_fmt < 0 or src_fmt > 9 or dst_fmt < 0 or dst_fmt > 9 or algo < 0 or algo > 2) return null;
    const c = alloc.create(Ctx) catch return null;
    c.* = .{
        .srcW = src_w,
        .srcH = src_h,
        .dstW = dst_w,
        .dstH = dst_h,
        .srcFmt = src_fmt,
        .dstFmt = dst_fmt,
        .algo = algo,
        .mode = .generic,
        .tabs = undefined,
        .c2y = initRgb2Yuv(),
    };
    initYuvTables(&c.tabs);
    const sf = src_fmt;
    const df = dst_fmt;
    const unscaled = src_w == dst_w and src_h == dst_h;
    if (unscaled) {
        if (sf == YUV420P and (df == NV12 or df == NV21)) c.mode = .planar_to_nv12;
        if (df == YUV420P and isSemi(sf)) c.mode = .nv12_to_planar;
        if ((sf == YUV420P or sf == YUV422P) and isRGB(df) and (dst_h & 1) == 0) c.mode = .yuv2rgb;
        if (sf == BGR24 and df == YUV420P and (dst_w & 1) == 0) c.mode = .bgr24_to_yv12;
        if (isRGB(sf) and isRGB(df)) c.mode = .rgb_to_rgb;
        if (sf == df) {
            c.mode = .copy_same;
        } else if ((isPlanarYUV(sf) and !isSemi(sf) and df == GRAY8) or
            (sf == GRAY8 and isPlanarYUV(df) and !isSemi(df)) or
            (isPlanarYUV(sf) and isPlanarYUV(df) and !isSemi(sf) and !isSemi(df) and
                hSub(sf) == hSub(df) and vSub(sf) == vSub(df)))
        {
            c.mode = .planar_copy;
        }
    }
    if (c.mode == .generic) {
        setupGeneric(c) catch {
            alloc.destroy(c);
            return null;
        };
    }
    return @ptrCast(c);
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return));
    if (c.hasFilters) {
        freeFilter(&c.hLum);
        freeFilter(&c.hChr);
        freeFilter(&c.vLum);
        freeFilter(&c.vChr);
        k.freePrepared(&c.hLum);
        k.freePrepared(&c.hChr);
        alloc.free(c.lumBuf);
        alloc.free(c.chrUBuf);
        alloc.free(c.chrVBuf);
        if (c.alpBuf.len > 0) alloc.free(c.alpBuf);
        alloc.free(c.lumDone);
        alloc.free(c.chrDone);
        alloc.free(c.tmpA);
        alloc.free(c.tmpB);
        alloc.free(c.tmpC);
        alloc.free(c.tmp8a);
        alloc.free(c.tmp8b);
    }
    alloc.destroy(c);
}

pub const Planes = struct {
    src: [4]?[*]const u8,
    ss: [4]usize,
    dst: [4]?[*]u8,
    ds: [4]usize,
};

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    var p: Planes = undefined;
    for (0..4) |i| {
        p.src[i] = src_data[i];
        p.dst[i] = dst_data[i];
        p.ss[i] = if (src_stride[i] > 0) @intCast(src_stride[i]) else 0;
        p.ds[i] = if (dst_stride[i] > 0) @intCast(dst_stride[i]) else 0;
    }
    switch (c.mode) {
        .generic => processGeneric(c, &p),
        .copy_same => copySame(c, &p),
        .planar_copy => planarCopy(c, &p),
        .yuv2rgb => k.yuv2rgbUnscaled(c, &p),
        .nv12_to_planar => nv12ToPlanar(c, &p),
        .planar_to_nv12 => planarToNv12(c, &p),
        .bgr24_to_yv12 => k.bgr24ToYv12(c, &p),
        .rgb_to_rgb => k.rgbToRgb(c, &p),
    }
    return 0;
}

// ── simple unscaled converters ──────────────────────────────────────────────

fn copyPlane(src: [*]const u8, ss: usize, dst: [*]u8, ds: usize, w: usize, h: usize) void {
    for (0..h) |y| @memcpy(dst[y * ds .. y * ds + w], src[y * ss .. y * ss + w]);
}

fn planeDims(f: i32, w: i32, h: i32, plane: usize) [2]usize {
    const ww: usize = @intCast(w);
    const hh: usize = @intCast(h);
    if (plane == 0) {
        return switch (f) {
            RGB24, BGR24 => .{ ww * 3, hh },
            RGBA, BGRA => .{ ww * 4, hh },
            else => .{ ww, hh },
        };
    }
    const cw: usize = @intCast(ceilShr(w, hSub(f)));
    const ch: usize = @intCast(ceilShr(h, vSub(f)));
    if (isSemi(f)) return .{ cw * 2, ch };
    return .{ cw, ch };
}

fn numPlanes(f: i32) usize {
    return switch (f) {
        YUV420P, YUV422P, YUV444P => 3,
        NV12, NV21 => 2,
        else => 1,
    };
}

fn copySame(c: *Ctx, p: *const Planes) void {
    for (0..numPlanes(c.srcFmt)) |i| {
        const d = planeDims(c.srcFmt, c.srcW, c.srcH, i);
        copyPlane(p.src[i].?, p.ss[i], p.dst[i].?, p.ds[i], d[0], d[1]);
    }
}

fn planarCopy(c: *Ctx, p: *const Planes) void {
    const d0 = planeDims(c.srcFmt, c.srcW, c.srcH, 0);
    copyPlane(p.src[0].?, p.ss[0], p.dst[0].?, p.ds[0], d0[0], d0[1]);
    if (c.dstFmt == GRAY8) return;
    for (1..3) |i| {
        const d = planeDims(c.dstFmt, c.dstW, c.dstH, i);
        if (c.srcFmt == GRAY8) {
            for (0..d[1]) |y| @memset(p.dst[i].?[y * p.ds[i] .. y * p.ds[i] + d[0]], 128);
        } else {
            copyPlane(p.src[i].?, p.ss[i], p.dst[i].?, p.ds[i], d[0], d[1]);
        }
    }
}

fn nv12ToPlanar(c: *Ctx, p: *const Planes) void {
    const d0 = planeDims(c.srcFmt, c.srcW, c.srcH, 0);
    copyPlane(p.src[0].?, p.ss[0], p.dst[0].?, p.ds[0], d0[0], d0[1]);
    const cw: usize = @intCast(ceilShr(c.srcW, 1));
    const ch: usize = @intCast(ceilShr(c.srcH, 1));
    const ui: usize = if (c.srcFmt == NV12) 1 else 2;
    const vi: usize = 3 - ui;
    for (0..ch) |y| {
        const s = p.src[1].? + y * p.ss[1];
        k.deinterleave(s, p.dst[ui].? + y * p.ds[ui], p.dst[vi].? + y * p.ds[vi], cw);
    }
}

fn planarToNv12(c: *Ctx, p: *const Planes) void {
    const d0 = planeDims(c.srcFmt, c.srcW, c.srcH, 0);
    copyPlane(p.src[0].?, p.ss[0], p.dst[0].?, p.ds[0], d0[0], d0[1]);
    const cw: usize = @intCast(ceilShr(c.srcW, 1));
    const ch: usize = @intCast(ceilShr(c.srcH, 1));
    const a: usize = if (c.dstFmt == NV12) 1 else 2;
    const b: usize = 3 - a;
    for (0..ch) |y| {
        k.interleave(p.src[a].? + y * p.ss[a], p.src[b].? + y * p.ss[b], p.dst[1].? + y * p.ds[1], cw);
    }
}

// ── generic pipeline ────────────────────────────────────────────────────────

fn ensureLumRow(c: *Ctx, p: *const Planes, y: usize) void {
    if (c.lumDone[y] != 0) return;
    c.lumDone[y] = 1;
    const sw: usize = @intCast(c.srcW);
    const out = c.lumBuf[y * c.lumStride ..];
    const sf = c.srcFmt;
    if (isRGB(sf)) {
        const row = p.src[0].? + y * p.ss[0];
        k.rgbToY(sf, row, c.tmpA.ptr, sw, &c.c2y);
        k.hScale16(&c.hLum, out.ptr, c.tmpA.ptr);
        if (c.needAlpha) {
            k.rgbToA(sf, row, c.tmpC.ptr, sw);
            k.hScale16(&c.hLum, c.alpBuf[y * c.lumStride ..].ptr, c.tmpC.ptr);
        }
    } else {
        k.hScale8(&c.hLum, out.ptr, p.src[0].? + y * p.ss[0]);
    }
}

fn ensureChrRow(c: *Ctx, p: *const Planes, y: usize) void {
    if (c.chrDone[y] != 0) return;
    c.chrDone[y] = 1;
    const sf = c.srcFmt;
    if (sf == GRAY8) return;
    const outU = c.chrUBuf[y * c.chrStride ..].ptr;
    const outV = c.chrVBuf[y * c.chrStride ..].ptr;
    const csw: usize = @intCast(c.chrSrcW);
    if (isRGB(sf)) {
        // RGB rows are full resolution vertically (chrSrcVSub == 0 for RGB)
        const row = p.src[0].? + y * p.ss[0];
        if (c.chrSrcHSub == 1) {
            k.rgbToUVHalf(sf, row, c.tmpA.ptr, c.tmpB.ptr, csw, &c.c2y);
        } else {
            k.rgbToUV(sf, row, c.tmpA.ptr, c.tmpB.ptr, csw, &c.c2y);
        }
        k.hScale16(&c.hChr, outU, c.tmpA.ptr);
        k.hScale16(&c.hChr, outV, c.tmpB.ptr);
    } else if (isSemi(sf)) {
        const row = p.src[1].? + y * p.ss[1];
        if (sf == NV12) k.deinterleave(row, c.tmp8a.ptr, c.tmp8b.ptr, csw) else k.deinterleave(row, c.tmp8b.ptr, c.tmp8a.ptr, csw);
        k.hScale8(&c.hChr, outU, c.tmp8a.ptr);
        k.hScale8(&c.hChr, outV, c.tmp8b.ptr);
    } else {
        k.hScale8(&c.hChr, outU, p.src[1].? + y * p.ss[1]);
        k.hScale8(&c.hChr, outV, p.src[2].? + y * p.ss[2]);
    }
}

pub const VRows = struct {
    rows: [*]const [*]const i16,
    coef: [*]const i16,
    n: usize,
};

fn processGeneric(c: *Ctx, p: *const Planes) void {
    @memset(c.lumDone, 0);
    @memset(c.chrDone, 0);
    const dh: usize = @intCast(c.dstH);
    const df = c.dstFmt;
    var lumRows: [64][*]const i16 = undefined;
    var chrURows: [64][*]const i16 = undefined;
    var chrVRows: [64][*]const i16 = undefined;
    var alpRows: [64][*]const i16 = undefined;
    const lfs = c.vLum.size;
    const cfs = c.vChr.size;
    const chrMask: usize = (@as(usize, 1) << c.chrDstVSub) - 1;
    for (0..dh) |dy| {
        const lp: usize = @intCast(c.vLum.pos[dy]);
        for (0..lfs) |j| {
            ensureLumRow(c, p, lp + j);
            lumRows[j] = c.lumBuf[(lp + j) * c.lumStride ..].ptr;
            if (c.needAlpha) alpRows[j] = c.alpBuf[(lp + j) * c.lumStride ..].ptr;
        }
        const lcoef = c.vLum.coef[dy * lfs ..].ptr;
        const doChr = (dy & chrMask) == 0 and df != GRAY8;
        const cy = dy >> c.chrDstVSub;
        var ccoef: [*]const i16 = undefined;
        if (doChr) {
            const cp: usize = @intCast(c.vChr.pos[cy]);
            for (0..cfs) |j| {
                ensureChrRow(c, p, cp + j);
                chrURows[j] = c.chrUBuf[(cp + j) * c.chrStride ..].ptr;
                chrVRows[j] = c.chrVBuf[(cp + j) * c.chrStride ..].ptr;
            }
            ccoef = c.vChr.coef[cy * cfs ..].ptr;
        }
        const lum = VRows{ .rows = &lumRows, .coef = lcoef, .n = lfs };
        const dw: usize = @intCast(c.dstW);
        if (isRGB(df)) {
            const chU = VRows{ .rows = &chrURows, .coef = ccoef, .n = cfs };
            const chV = VRows{ .rows = &chrVRows, .coef = ccoef, .n = cfs };
            const alp: ?VRows = if (c.needAlpha) VRows{ .rows = &alpRows, .coef = lcoef, .n = lfs } else null;
            const out = p.dst[0].? + dy * p.ds[0];
            if (c.fullChr) {
                k.outRgbFull(c, out, dw, lum, chU, chV, alp);
            } else {
                k.outRgbHalf(c, out, dw, lum, chU, chV);
            }
        } else {
            k.vPlanar(lum, p.dst[0].? + dy * p.ds[0], dw);
            if (doChr) {
                const cdw: usize = @intCast(c.chrDstW);
                const chU = VRows{ .rows = &chrURows, .coef = ccoef, .n = cfs };
                const chV = VRows{ .rows = &chrVRows, .coef = ccoef, .n = cfs };
                if (isSemi(df)) {
                    const out = p.dst[1].? + cy * p.ds[1];
                    if (df == NV12) k.vInterleaved(chU, chV, out, cdw) else k.vInterleaved(chV, chU, out, cdw);
                } else {
                    k.vPlanar(chU, p.dst[1].? + cy * p.ds[1], cdw);
                    k.vPlanar(chV, p.dst[2].? + cy * p.ds[2], cdw);
                }
            }
        }
    }
}

