// kernels.zig — per-row kernels for the swscale candidate.

const std = @import("std");
const m = @import("main.zig");

const Filter = m.Filter;
const Ctx = m.Ctx;
const Planes = m.Planes;
const VRows = m.VRows;

pub fn prepareHFilter(f: *Filter) void {
    _ = f;
}
pub fn freePrepared(f: *Filter) void {
    _ = f;
}

inline fn clipU8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}

// ── input conversion ────────────────────────────────────────────────────────

pub fn rgbToY(sf: i32, row: [*]const u8, out: [*]i16, w: usize, t: *const m.Rgb2Yuv) void {
    const L = m.layout(sf);
    for (0..w) |i| {
        const r: i32 = row[i * L.bpp + L.r];
        const g: i32 = row[i * L.bpp + L.g];
        const b: i32 = row[i * L.bpp + L.b];
        out[i] = @intCast((t.ry * r + t.gy * g + t.by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToA(sf: i32, row: [*]const u8, out: [*]i16, w: usize) void {
    const L = m.layout(sf);
    for (0..w) |i| {
        const a: i16 = row[i * L.bpp + L.a];
        out[i] = (a << 6) | (a >> 2);
    }
}

pub fn rgbToUV(sf: i32, row: [*]const u8, ou: [*]i16, ov: [*]i16, w: usize, t: *const m.Rgb2Yuv) void {
    const L = m.layout(sf);
    for (0..w) |i| {
        const r: i32 = row[i * L.bpp + L.r];
        const g: i32 = row[i * L.bpp + L.g];
        const b: i32 = row[i * L.bpp + L.b];
        ou[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 14) + (1 << 8)) >> 9);
        ov[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUVHalf(sf: i32, row: [*]const u8, ou: [*]i16, ov: [*]i16, w: usize, t: *const m.Rgb2Yuv) void {
    const L = m.layout(sf);
    const bp = L.bpp;
    for (0..w) |i| {
        const r: i32 = @as(i32, row[2 * i * bp + L.r]) + row[(2 * i + 1) * bp + L.r];
        const g: i32 = @as(i32, row[2 * i * bp + L.g]) + row[(2 * i + 1) * bp + L.g];
        const b: i32 = @as(i32, row[2 * i * bp + L.b]) + row[(2 * i + 1) * bp + L.b];
        ou[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 15) + (1 << 9)) >> 10);
        ov[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

// ── horizontal scaling ──────────────────────────────────────────────────────

pub fn hScale8(f: *const Filter, out: [*]i16, src: [*]const u8) void {
    const fs = f.size;
    for (0..f.n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var v: i32 = 0;
        for (0..fs) |j| v += @as(i32, src[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(v >> 7, 32767));
    }
}

pub fn hScale16(f: *const Filter, out: [*]i16, src: [*]const i16) void {
    const fs = f.size;
    for (0..f.n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var v: i32 = 0;
        for (0..fs) |j| v += @as(i32, @as(u16, @bitCast(src[p + j]))) * f.coef[i * fs + j];
        out[i] = @intCast(@min(v >> 13, 32767));
    }
}

// ── vertical scaling / output ───────────────────────────────────────────────

pub fn vPlanar(r: VRows, out: [*]u8, w: usize) void {
    if (r.n == 1) {
        const s = r.rows[0];
        for (0..w) |i| out[i] = clipU8((@as(i32, s[i]) + 64) >> 7);
        return;
    }
    for (0..w) |i| {
        var v: i32 = 64 << 12;
        for (0..r.n) |j| v += @as(i32, r.rows[j][i]) * r.coef[j];
        out[i] = clipU8(v >> 19);
    }
}

pub fn vInterleaved(u: VRows, v: VRows, out: [*]u8, w: usize) void {
    for (0..w) |i| {
        var a: i32 = 64 << 12;
        var b: i32 = 64 << 12;
        for (0..u.n) |j| {
            a += @as(i32, u.rows[j][i]) * u.coef[j];
            b += @as(i32, v.rows[j][i]) * v.coef[j];
        }
        out[2 * i] = clipU8(a >> 19);
        out[2 * i + 1] = clipU8(b >> 19);
    }
}

fn twoTapOk(coef: [*]const i16) bool {
    const c0: i32 = coef[0];
    const c1: i32 = coef[1];
    return c1 >= 0 and c1 <= 4096 and c0 >= 0 and c0 + c1 == 4096;
}

inline fn writeFull(c: *const Ctx, out: [*]u8, i: usize, Y0: i32, U: i32, V: i32, A: i32) void {
    const t = &c.tabs;
    var Y = Y0 -% t.y_off;
    Y = Y *% t.y_coeff;
    Y +%= 1 << 21;
    var R = Y +% V *% t.v2r;
    var G = Y +% V *% t.v2g +% U *% t.u2g;
    var B = Y +% U *% t.u2b;
    if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
        R = std.math.clamp(R, 0, (1 << 30) - 1);
        G = std.math.clamp(G, 0, (1 << 30) - 1);
        B = std.math.clamp(B, 0, (1 << 30) - 1);
    }
    const L = m.layout(c.dstFmt);
    const o = out + i * L.bpp;
    o[L.r] = @intCast(R >> 22);
    o[L.g] = @intCast(G >> 22);
    o[L.b] = @intCast(B >> 22);
    if (L.bpp == 4) o[L.a] = @intCast(A);
}

pub fn outRgbFull(c: *const Ctx, out: [*]u8, w: usize, lum: VRows, u: VRows, v: VRows, alp: ?VRows) void {
    const hasA = alp != null;
    if (lum.n == 1 and (u.n == 1 or (u.n == 2 and twoTapOk(u.coef)))) {
        const uvalpha: i32 = if (u.n == 1) 0 else u.coef[1];
        const b0 = lum.rows[0];
        const ub0 = u.rows[0];
        const vb0 = v.rows[0];
        for (0..w) |i| {
            const Y = @as(i32, b0[i]) * 4;
            var U: i32 = undefined;
            var V: i32 = undefined;
            if (uvalpha < 2048) {
                U = (@as(i32, ub0[i]) - (128 << 7)) * 4;
                V = (@as(i32, vb0[i]) - (128 << 7)) * 4;
            } else {
                U = (@as(i32, ub0[i]) + u.rows[1][i] - (128 << 8)) * 2;
                V = (@as(i32, vb0[i]) + v.rows[1][i] - (128 << 8)) * 2;
            }
            var A: i32 = 255;
            if (hasA) {
                A = (@as(i32, alp.?.rows[0][i]) + 64) >> 7;
                if (A & 0x100 != 0) A = clipU8(A);
            }
            writeFull(c, out, i, Y, U, V, A);
        }
    } else if (lum.n == 2 and u.n == 2 and twoTapOk(lum.coef) and twoTapOk(u.coef)) {
        const ya: i32 = lum.coef[1];
        const ya1: i32 = 4096 - ya;
        const ua: i32 = u.coef[1];
        const ua1: i32 = 4096 - ua;
        for (0..w) |i| {
            const Y = (@as(i32, lum.rows[0][i]) * ya1 + @as(i32, lum.rows[1][i]) * ya) >> 10;
            const U = (@as(i32, u.rows[0][i]) * ua1 + @as(i32, u.rows[1][i]) * ua - (128 << 19)) >> 10;
            const V = (@as(i32, v.rows[0][i]) * ua1 + @as(i32, v.rows[1][i]) * ua - (128 << 19)) >> 10;
            var A: i32 = 255;
            if (hasA) {
                A = (@as(i32, alp.?.rows[0][i]) * ya1 + @as(i32, alp.?.rows[1][i]) * ya + (1 << 18)) >> 19;
                if (A & 0x100 != 0) A = clipU8(A);
            }
            writeFull(c, out, i, Y, U, V, A);
        }
    } else {
        for (0..w) |i| {
            var Y: i32 = 1 << 9;
            var U: i32 = (1 << 9) - (128 << 19);
            var V: i32 = (1 << 9) - (128 << 19);
            for (0..lum.n) |j| Y += @as(i32, lum.rows[j][i]) * lum.coef[j];
            for (0..u.n) |j| {
                U += @as(i32, u.rows[j][i]) * u.coef[j];
                V += @as(i32, v.rows[j][i]) * v.coef[j];
            }
            Y >>= 10;
            U >>= 10;
            V >>= 10;
            var A: i32 = 255;
            if (hasA) {
                A = 1 << 18;
                for (0..lum.n) |j| A += @as(i32, alp.?.rows[j][i]) * lum.coef[j];
                A >>= 19;
                if (A & 0x100 != 0) A = clipU8(A);
            }
            writeFull(c, out, i, Y, U, V, A);
        }
    }
}

inline fn tabIdx(v: i32) usize {
    return @intCast(std.math.clamp(v, 0, 2047));
}

inline fn writeHalf(c: *const Ctx, out: [*]u8, i: usize, Y1: i32, Y2: i32, U0: i32, V0: i32) void {
    const t = &c.tabs;
    const U: usize = @intCast(std.math.clamp(U0, 0, 255));
    const V: usize = @intCast(std.math.clamp(V0, 0, 255));
    const ro = t.rOff[V];
    const go = t.gUOff[U] + t.gVOff[V];
    const bo = t.bOff[U];
    const L = m.layout(c.dstFmt);
    const o = out + 2 * i * L.bpp;
    o[L.r] = t.ytab[tabIdx(ro + Y1)];
    o[L.g] = t.ytab[tabIdx(go + Y1)];
    o[L.b] = t.ytab[tabIdx(bo + Y1)];
    o[L.bpp + L.r] = t.ytab[tabIdx(ro + Y2)];
    o[L.bpp + L.g] = t.ytab[tabIdx(go + Y2)];
    o[L.bpp + L.b] = t.ytab[tabIdx(bo + Y2)];
    if (L.bpp == 4) {
        o[L.a] = 255;
        o[L.bpp + L.a] = 255;
    }
}

pub fn outRgbHalf(c: *const Ctx, out: [*]u8, w: usize, lum: VRows, u: VRows, v: VRows) void {
    const n2 = (w + 1) >> 1;
    if (lum.n == 1 and (u.n == 1 or (u.n == 2 and twoTapOk(u.coef)))) {
        const uvalpha: i32 = if (u.n == 1) 0 else u.coef[1];
        const b0 = lum.rows[0];
        for (0..n2) |i| {
            const Y1 = (@as(i32, b0[2 * i]) + 64) >> 7;
            const Y2 = (@as(i32, b0[2 * i + 1]) + 64) >> 7;
            var U: i32 = undefined;
            var V: i32 = undefined;
            if (uvalpha < 2048) {
                U = (@as(i32, u.rows[0][i]) + 64) >> 7;
                V = (@as(i32, v.rows[0][i]) + 64) >> 7;
            } else {
                U = (@as(i32, u.rows[0][i]) + u.rows[1][i] + 128) >> 8;
                V = (@as(i32, v.rows[0][i]) + v.rows[1][i] + 128) >> 8;
            }
            writeHalf(c, out, i, Y1, Y2, U, V);
        }
    } else if (lum.n == 2 and u.n == 2 and twoTapOk(lum.coef) and twoTapOk(u.coef)) {
        const ya: i32 = lum.coef[1];
        const ya1: i32 = 4096 - ya;
        const ua: i32 = u.coef[1];
        const ua1: i32 = 4096 - ua;
        for (0..n2) |i| {
            const Y1 = (@as(i32, lum.rows[0][2 * i]) * ya1 + @as(i32, lum.rows[1][2 * i]) * ya) >> 19;
            const Y2 = (@as(i32, lum.rows[0][2 * i + 1]) * ya1 + @as(i32, lum.rows[1][2 * i + 1]) * ya) >> 19;
            const U = (@as(i32, u.rows[0][i]) * ua1 + @as(i32, u.rows[1][i]) * ua) >> 19;
            const V = (@as(i32, v.rows[0][i]) * ua1 + @as(i32, v.rows[1][i]) * ua) >> 19;
            writeHalf(c, out, i, Y1, Y2, U, V);
        }
    } else {
        for (0..n2) |i| {
            var Y1: i32 = 1 << 18;
            var Y2: i32 = 1 << 18;
            var U: i32 = 1 << 18;
            var V: i32 = 1 << 18;
            for (0..lum.n) |j| {
                Y1 += @as(i32, lum.rows[j][2 * i]) * lum.coef[j];
                Y2 += @as(i32, lum.rows[j][2 * i + 1]) * lum.coef[j];
            }
            for (0..u.n) |j| {
                U += @as(i32, u.rows[j][i]) * u.coef[j];
                V += @as(i32, v.rows[j][i]) * v.coef[j];
            }
            writeHalf(c, out, i, Y1 >> 19, Y2 >> 19, U >> 19, V >> 19);
        }
    }
}

// ── unscaled special converters ─────────────────────────────────────────────

pub fn yuv2rgbUnscaled(c: *const Ctx, p: *const Planes) void {
    const w: usize = @intCast(c.dstW);
    const h: usize = @intCast(c.dstH);
    const is422 = c.srcFmt == m.YUV422P;
    const t = &c.tabs;
    const L = m.layout(c.dstFmt);
    var y: usize = 0;
    while (y < h) : (y += 1) {
        const cy = if (is422) y else y >> 1;
        const py = p.src[0].? + y * p.ss[0];
        const pu = p.src[1].? + cy * p.ss[1];
        const pv = p.src[2].? + cy * p.ss[2];
        const o = p.dst[0].? + y * p.ds[0];
        for (0..w / 2) |i| {
            const U = pu[i];
            const V = pv[i];
            const ro = t.rOff[V];
            const go = t.gUOff[U] + t.gVOff[V];
            const bo = t.bOff[U];
            inline for (0..2) |kk| {
                const Y: i32 = py[2 * i + kk];
                const q = o + (2 * i + kk) * L.bpp;
                q[L.r] = t.ytab[@intCast(ro + Y)];
                q[L.g] = t.ytab[@intCast(go + Y)];
                q[L.b] = t.ytab[@intCast(bo + Y)];
                if (L.bpp == 4) q[L.a] = 255;
            }
        }
    }
}

pub fn bgr24ToYv12(c: *const Ctx, p: *const Planes) void {
    const t = &c.c2y;
    const w: usize = @intCast(c.srcW);
    const h: usize = @intCast(c.srcH);
    var y: usize = 0;
    while (y + 1 < h) : (y += 2) {
        const s1 = p.src[0].? + y * p.ss[0];
        const s2 = s1 + p.ss[0];
        const y1 = p.dst[0].? + y * p.ds[0];
        const y2 = y1 + p.ds[0];
        const ud = p.dst[1].? + (y >> 1) * p.ds[1];
        const vd = p.dst[2].? + (y >> 1) * p.ds[2];
        for (0..w / 2) |i| {
            var bs: i32 = 0;
            var gs: i32 = 0;
            var rs: i32 = 0;
            inline for (0..2) |row| {
                const s = if (row == 0) s1 else s2;
                const d = if (row == 0) y1 else y2;
                inline for (0..2) |kk| {
                    const b: i32 = s[6 * i + 3 * kk];
                    const g: i32 = s[6 * i + 3 * kk + 1];
                    const r: i32 = s[6 * i + 3 * kk + 2];
                    d[2 * i + kk] = @truncate(@as(u32, @bitCast((t.ry * r + t.gy * g + t.by * b) >> 15)) +% 16);
                    bs += b;
                    gs += g;
                    rs += r;
                }
            }
            const bx = bs >> 2;
            const gx = gs >> 2;
            const rx = rs >> 2;
            ud[i] = @truncate(@as(u32, @bitCast((t.ru * rx + t.gu * gx + t.bu * bx) >> 15)) +% 128);
            vd[i] = @truncate(@as(u32, @bitCast((t.rv * rx + t.gv * gx + t.bv * bx) >> 15)) +% 128);
        }
    }
}

pub fn rgbToRgb(c: *const Ctx, p: *const Planes) void {
    const S = m.layout(c.srcFmt);
    const D = m.layout(c.dstFmt);
    const w: usize = @intCast(c.srcW);
    const h: usize = @intCast(c.srcH);
    for (0..h) |y| {
        const s = p.src[0].? + y * p.ss[0];
        const d = p.dst[0].? + y * p.ds[0];
        for (0..w) |i| {
            d[i * D.bpp + D.r] = s[i * S.bpp + S.r];
            d[i * D.bpp + D.g] = s[i * S.bpp + S.g];
            d[i * D.bpp + D.b] = s[i * S.bpp + S.b];
            if (D.bpp == 4) d[i * D.bpp + D.a] = if (S.bpp == 4) s[i * S.bpp + S.a] else 255;
        }
    }
}

pub fn deinterleave(s: [*]const u8, a: [*]u8, b: [*]u8, n: usize) void {
    for (0..n) |i| {
        a[i] = s[2 * i];
        b[i] = s[2 * i + 1];
    }
}

pub fn interleave(a: [*]const u8, b: [*]const u8, d: [*]u8, n: usize) void {
    for (0..n) |i| {
        d[2 * i] = a[i];
        d[2 * i + 1] = b[i];
    }
}

