// simd.zig — @Vector kernels for the hot paths (AVX2 width: 8 x i32 / 16 x i16).

const std = @import("std");
const m = @import("main.zig");

pub const V8i32 = @Vector(8, i32);
pub const V16i16 = @Vector(16, i16);
pub const V16i32 = @Vector(16, i32);
pub const V16u8 = @Vector(16, u8);
pub const V8i16 = @Vector(8, i16);

pub inline fn splat(comptime T: type, v: anytype) T {
    return @splat(v);
}

pub inline fn load(comptime N: usize, comptime T: type, p: [*]const T) @Vector(N, T) {
    return p[0..N].*;
}

pub inline fn store(comptime N: usize, comptime T: type, p: [*]T, v: @Vector(N, T)) void {
    p[0..N].* = v;
}

// (a * b + 0x4000) >> 15 per i16 lane (pmulhrsw pattern)
pub inline fn mulhrs(a: V16i16, b: V16i16) V16i16 {
    const p = @as(V16i32, a) * @as(V16i32, b);
    return @truncate((p + splat(V16i32, 0x4000)) >> splat(@Vector(16, u5), 15));
}

pub inline fn packU8(v: V16i16) V16u8 {
    return @intCast(@min(@max(v, splat(V16i16, 0)), splat(V16i16, 255)));
}

pub inline fn packU8x8(v: V8i32) @Vector(8, u8) {
    return @intCast(@min(@max(v, splat(V8i32, 0)), splat(V8i32, 255)));
}

// Extract channel `ch` (stride `bpp`) of N pixels from packed bytes.
pub inline fn deint(comptime N: usize, comptime bpp: usize, comptime ch: usize, v: @Vector(N * bpp, u8)) @Vector(N, u8) {
    comptime var mask: [N]i32 = undefined;
    inline for (0..N) |i| mask[i] = @intCast(i * bpp + ch);
    return @shuffle(u8, v, undefined, mask);
}

// Interleave three N-lane byte vectors as packed (c0,c1,c2) triples.
pub inline fn interleave3(comptime N: usize, a: @Vector(N, u8), b: @Vector(N, u8), c: @Vector(N, u8)) @Vector(3 * N, u8) {
    comptime var m1: [2 * N]i32 = undefined;
    inline for (0..N) |i| {
        m1[2 * i] = @intCast(i);
        m1[2 * i + 1] = ~@as(i32, @intCast(i));
    }
    const ab = @shuffle(u8, a, b, m1);
    comptime var m2: [3 * N]i32 = undefined;
    inline for (0..N) |i| {
        m2[3 * i] = @intCast(2 * i);
        m2[3 * i + 1] = @intCast(2 * i + 1);
        m2[3 * i + 2] = ~@as(i32, @intCast(i));
    }
    const cc: @Vector(2 * N, u8) = @shuffle(u8, c, undefined, comptime blk: {
        var mm: [2 * N]i32 = undefined;
        for (0..2 * N) |i| mm[i] = @intCast(i % N);
        break :blk mm;
    });
    return @shuffle(u8, ab, cc, m2);
}

pub inline fn interleave4(comptime N: usize, a: @Vector(N, u8), b: @Vector(N, u8), c: @Vector(N, u8), d: @Vector(N, u8)) @Vector(4 * N, u8) {
    comptime var m1: [2 * N]i32 = undefined;
    inline for (0..N) |i| {
        m1[2 * i] = @intCast(i);
        m1[2 * i + 1] = ~@as(i32, @intCast(i));
    }
    const ab = @shuffle(u8, a, b, m1);
    const cd = @shuffle(u8, c, d, m1);
    comptime var m2: [4 * N]i32 = undefined;
    inline for (0..N) |i| {
        m2[4 * i] = @intCast(2 * i);
        m2[4 * i + 1] = @intCast(2 * i + 1);
        m2[4 * i + 2] = ~@as(i32, @intCast(2 * i));
        m2[4 * i + 3] = ~@as(i32, @intCast(2 * i + 1));
    }
    return @shuffle(u8, ab, cd, m2);
}

// Store N pixels of r,g,b(,a) bytes in the packed layout of `fmt`.
pub inline fn storeRgb(comptime fmt: i32, comptime N: usize, out: [*]u8, r: @Vector(N, u8), g: @Vector(N, u8), b: @Vector(N, u8), a: @Vector(N, u8)) void {
    switch (fmt) {
        m.RGB24 => store(3 * N, u8, out, interleave3(N, r, g, b)),
        m.BGR24 => store(3 * N, u8, out, interleave3(N, b, g, r)),
        m.RGBA => store(4 * N, u8, out, interleave4(N, r, g, b, a)),
        else => store(4 * N, u8, out, interleave4(N, b, g, r, a)),
    }
}

pub const Px = struct { r: V16u8, g: V16u8, b: V16u8, a: V16u8 };

pub inline fn loadRgb(comptime fmt: i32, p: [*]const u8) Px {
    const L = comptime m.layout(fmt);
    const v = load(16 * L.bpp, u8, p);
    return .{
        .r = deint(16, L.bpp, L.r, v),
        .g = deint(16, L.bpp, L.g, v),
        .b = deint(16, L.bpp, L.b, v),
        .a = if (L.bpp == 4) deint(16, 4, L.a, v) else splat(V16u8, 255),
    };
}

