fn rgbToYT(comptime sf: i32, row: [*]const u8, out: [*]i16, w: usize, t: *const m.Rgb2Yuv, ident: bool) void {
    const L = comptime m.layout(sf);
    var i: usize = 0;
    const ry = v.splat(V16i32, t.ry);
    const gy = v.splat(V16i32, t.gy);
