    bq: V16i16, br: @Vector(16, u16),
    guq: V16i16, gur: @Vector(16, u16),
    gvq: V16i16, gvr: @Vector(16, u16),
    rb: V16i16, gb: V16i16, bb: V16i16,
    cf: V16i16, ysub: V16i16,

    pub fn init(t: *const m.YuvTables) ChrK {
        const s9: u5 = 9;
        return .{
            .rq = sv.splat(V16i16, @intCast(t.crvS >> 16)), .rr = sv.splat(@Vector(16, u16), @truncate(@as(u32, @bitCast(t.crvS)))),
            .bq = sv.splat(V16i16, @intCast(t.cbuS >> 16)), .br = sv.splat(@Vector(16, u16), @truncate(@as(u32, @bitCast(t.cbuS)))),
            .guq = sv.splat(V16i16, @intCast(t.cguS >> 16)), .gur = sv.splat(@Vector(16, u16), @truncate(@as(u32, @bitCast(t.cguS)))),
            .gvq = sv.splat(V16i16, @intCast(t.cgvS >> 16)), .gvr = sv.splat(@Vector(16, u16), @truncate(@as(u32, @bitCast(t.cgvS)))),
