// ── exact 16x16->32 products in 16-bit lanes (pmullw/pmulhw + unpack) ──────
// Sums are kept in "unpack order": lo = lanes {0-3, 8-11}, hi = lanes {4-7, 12-15}.
pub const P = struct { lo: V8i32, hi: V8i32 };

const ulo = [16]i32{ 0, ~@as(i32, 0), 1, ~@as(i32, 1), 2, ~@as(i32, 2), 3, ~@as(i32, 3), 8, ~@as(i32, 8), 9, ~@as(i32, 9), 10, ~@as(i32, 10), 11, ~@as(i32, 11) };
const uhi = [16]i32{ 4, ~@as(i32, 4), 5, ~@as(i32, 5), 6, ~@as(i32, 6), 7, ~@as(i32, 7), 12, ~@as(i32, 12), 13, ~@as(i32, 13), 14, ~@as(i32, 14), 15, ~@as(i32, 15) };

pub inline fn pinit(v: i32) P {
    return .{ .lo = sv.splat(V8i32, v), .hi = sv.splat(V8i32, v) };
}

pub inline fn macc(acc: *P, x: V16i16, c: i16) void {
    const cv = sv.splat(V16i16, c);
    const l = x *% cv;
    const h: V16i16 = @truncate((@as(V16i32, x) * @as(V16i32, cv)) >> sv.splat(@Vector(16, u5), 16));
    acc.lo +%= @bitCast(@shuffle(i16, l, h, ulo));
    acc.hi +%= @bitCast(@shuffle(i16, l, h, uhi));
}

pub inline fn pshr(a: P, comptime s: u5) P {
    return .{ .lo = a.lo >> sv.splat(@Vector(8, u5), s), .hi = a.hi >> sv.splat(@Vector(8, u5), s) };
}

pub inline fn natural(a: P) V16i32 {
    return @shuffle(i32, a.lo, a.hi, [16]i32{ 0, 1, 2, 3, ~@as(i32, 0), ~@as(i32, 1), ~@as(i32, 2), ~@as(i32, 3), 4, 5, 6, 7, ~@as(i32, 4), ~@as(i32, 5), ~@as(i32, 6), ~@as(i32, 7) });
}

inline fn vsumP(r: VRows, i: usize, init: i32) P {
    var acc = pinit(init);
    for (0..r.n) |j| macc(&acc, sv.load(16, i16, r.rows[j] + i), r.coef[j]);
    return acc;
}

